part of '../site.dart';

const _sw = SiteText(
  title: 'OpenCADIrrigation: programu ya bure ya kusanifu umwagiliaji na AI',
  description: 'Programu ya bure na huria ya usanifu wa umwagiliaji: msaidizi wa AI hupanga vinyunyizio na matone, hutandaza mabomba na hupima ukubwa wa mfumo kivinjarini.',
  keywords: 'usanifu wa umwagiliaji kwa AI, usanifu wa umwagiliaji kwa akili bandia, programu ya usanifu wa umwagiliaji kwa AI, usanifu wa umwagiliaji kiotomatiki, mpangilio wa vinyunyizio kiotomatiki, msaidizi wa AI wa umwagiliaji, usanifu wa umwagiliaji, programu ya usanifu wa umwagiliaji, programu huria ya umwagiliaji, programu ya umwagiliaji, CAD umwagiliaji, umwagiliaji wa shinikizo, umwagiliaji wa matone, vinyunyizio, pivoti ya kati, ukokotoaji wa haidroliki, vipimo vya mabomba, usawa wa umwagiliaji, DXF, DWG, umwagiliaji wa bustani, umwagiliaji wa kilimo',
  h1: 'Programu ya bure na huria ya usanifu wa umwagiliaji yenye msaidizi wa AI',
  tagline: 'Eleza shamba, bustani au uwanja kisha umwachie msaidizi wa AI apange vinyunyizio na matone, atandaze mabomba na apime ukubwa wa mfumo; au uchore mwenyewe kwa zana za kiotomatiki. Kwa mifumo ya matone, vinyunyizio vidogo, vinyunyizio na pivoti ya kati, moja kwa moja kwenye kivinjari, bila kusakinisha chochote, na miradi yako ikibaki kwenye kompyuta yako.',
  intro: 'OpenCADIrrigation huunganisha mchoro wa CAD, mtandao wa haidroliki, ukokotoaji na msaidizi wa AI mahali pamoja. Chora eneo, au iache AI itafute mahali pa mradi kwenye picha ya setilaiti; weka laterali, vali na bomba kuu kwa mkono, kwa zana za mbofyo mmoja au kwa kuiomba AI; bonyeza F5 na upate vipimo vya mabomba, shinikizo, usawa, zamu za uendeshaji, orodha ya vifaa na ripoti tayari kuchapishwa. Msaidizi hutumia modeli za Claude (Anthropic) au GPT (OpenAI) kwa ufunguo wako mwenyewe wa API, moja kwa moja kutoka kivinjari. Inapatikana kwa lugha 20, ikifuata lugha ya kompyuta yako.',
  openApp: 'Fungua programu',
  tutorial: 'Mafunzo shirikishi',
  seeExamples: 'Tazama mifano iliyo tayari',
  aiTitle: 'Msaidizi wa AI anayechora na kusanifu pamoja nawe',
  aiIntro: 'Fungua paneli ya AI kando ya mchoro na uombe unachohitaji kwa maneno yako mwenyewe. Msaidizi husoma mradi, hutazama picha ya setilaiti na ardhi, na hufanya kazi kwa zana zilezile zilizo kwenye menyu, kwa hiyo anachochora ni usanifu halisi: vipengele, mabomba, vali, kanda na matokeo, si picha tu. Kila badiliko husubiri idhini yako, au hutumika kiotomatiki ukipenda, na linaweza kutenduliwa kwa mbofyo mmoja.',
  aiPoints: [
    ('Huchora na kusanifu kiotomatiki', 'Hupanga vinyunyizio na mistari ya matone, hugawa mashamba katika vitalu, hulinganisha pivoti na mashamba, hupanga njia za mabomba na vali, huweka pampu na chanzo cha maji, huendesha usanifu, hurekebisha maonyo na hupunguza gharama, kisha huandika ripoti ya kiufundi na nukuu ya bei.'),
    ('Huona eneo la mradi', 'Hupata eneo kutokana na anwani, hutazama picha ya setilaiti ya mradi wenye marejeleo ya kijiografia pamoja na ardhi yake (mandhari yenye kivuli, kontua, mteremko, wasifu wa mwinuko), husoma michoro na faili za GIS unazoambatisha na huongeza kwenye katalogi vipengele kutoka karatasi ya data ya PDF. Huchora mwenyewe mipaka ya mashamba kwenye picha, hufuata nukta na mistari unayoiwekea alama kwenye ramani, na hubandika kwenye mchoro picha za shambani zenye GPS mahali zilipopigwa.'),
    ('Hueleza na kukagua', 'Hujibu maswali kuhusu mradi na matokeo yake, hueleza kila ujumbe wa usanifu na jinsi ya kuurekebisha, huendesha uchanganuzi na huhifadhi ndani ya mradi orodha ya mambo ya kufanya na madokezo ya maamuzi yako. Ukiomba, hukagua usanifu wote bila kubadilisha chochote, na hutazama karatasi ya mchoro kabla hujaihamisha.'),
    ('Ufunguo wako, udhibiti wako', 'Modeli za Claude (Anthropic) au GPT (OpenAI) za daraja la juu, la kati na la haraka, kwa ufunguo wako mwenyewe wa API, na maombi hutumwa moja kwa moja kutoka kivinjari bila seva yoyote katikati. Hali za kusoma tu, mpango kwanza, kuuliza kabla ya kila badiliko au kutumia mabadiliko kiotomatiki; kikomo cha hatua na kikomo cha matumizi kwa kila kazi; kila jibu linaweza kutenduliwa, na hakuna kinachotumwa kabla hujabonyeza Tuma.'),
  ],
  aiCta: 'Fungua msaidizi wa AI',
  featuresTitle: 'OpenCADIrrigation hufanya nini',
  features: [
    ('Msaidizi wa AI', 'Ni wa hiari: iulize AI kuhusu mradi, au iache ikuchoree na ikusanifie mradi. Hupanga vinyunyizio na matone, hugawa mashamba, hupanga njia za mabomba, huendesha upimaji wa ukubwa na zana za kiotomatiki, ikitazama picha ya setilaiti na ardhi, kwa modeli za Claude (Anthropic) au GPT (OpenAI) na ufunguo wako mwenyewe wa API, moja kwa moja kutoka kivinjari bila seva yoyote katikati. Hakuna kinachotumwa kabla hujabonyeza Tuma, na kila badiliko husubiri idhini yako (au hutumika kiotomatiki, ukichagua hivyo) na linaweza kutenduliwa.'),
    ('Usanifu na upimaji wa ukubwa kiotomatiki', 'Makundi ya laterali na gridi za vinyunyizio kwa mbofyo mmoja, mpangilio wa vinyunyizio wenye mvua iliyolinganishwa, ugawaji wa kanda kulingana na mtiririko, upangaji wa njia za mabomba na vali, mgawanyo wa shamba katika vitalu, kulinganisha pivoti na shamba na utambuzi wa uoto kwenye picha za angani; mabomba hupimwa kwa linear programming ndani ya dirisha la shinikizo la vitoa-maji na daraja la shinikizo la mabomba, huku gharama ya mabomba ikisawazishwa na ya nishati.'),
    ('Mchoro kamili wa CAD', 'Mistari, polyline, tao, spline, vivuli, vipimo, maandishi, tabaka na bloku, pamoja na kuratibu zinazoandikwa, snap, ufuatiliaji wa polar, grips, mawingu ya marekebisho na njia za mkato za mtindo wa AutoCAD (L, PL, C, D, ZE…).'),
    ('Mtandao wa haidroliki', 'Vyanzo vya maji, pampu za kasi isiyobadilika au inayobadilika, bomba kuu, vali za kanda, za kupunguza shinikizo, za kudumisha shinikizo na za kudhibiti mtiririko, vinyunyizio vyenye vali ndani ya kichwa, laterali zenye vitoa-maji, tepu za matone, vichujio na mita za maji, pamoja na pivoti za kati na mashine za mstari zenye seti zao za vinyunyizio, bunduki zinazotembea za hosi na umwagiliaji wa juu ya ardhi.'),
    ('Injini ya haidroliki iliyothibitishwa', 'Hazen-Williams, Darcy-Weisbach, Scobey na Manning, upotevu mdogo kutokana na viungo vilivyotumika, vitoa-maji q = k·Hˣ, utatuzi wa mtandao kwa Global Gradient Algorithm (kama EPANET), mikunjo ya pampu yenye NPSH, hali za mpito (nyundo ya maji) kwa method of characteristics pamoja na vali za hewa, na uigaji wa saa 24 unaozingatia bei za umeme.'),
    ('Ardhi, hali ya hewa na kilimo', 'Mistari ya kontua, nukta za kimo, modeli ya ardhi kwa pembetatu yenye mistari ya mvunjiko, mwinuko unaopakuliwa kutoka intaneti, mawingu ya nukta ya LAS, ramani za mteremko na wasifu wa mwinuko; hali ya hewa ya eneo inayopakuliwa au kuingizwa kwa mkono, mazao ya FAO-56 kwa hatua za ukuaji, aina za udongo, mvua yenye manufaa na uoshaji wa chumvi kwa mahitaji ya maji, pamoja na bajeti za maji za mandhari.'),
    ('Ripoti, michoro na vifaa', 'Kanda, mabomba, vitoa-maji, usawa (CU, DU, EU), programu ya kidhibiti na nyaya za vali; orodha ya vifaa pamoja na viungo, na nukuu ya bei yenye ujira, kodi na muda wa kurudisha mtaji; seti za karatasi za PDF zenye michoro ya kina ya ujenzi na chati, kwa lugha yoyote kati ya 20, na kila jedwali katika Excel, CSV na TXT.'),
    ('Ubadilishanaji wa faili', 'Huingiza DXF, DWG, michoro ya PDF, KML/KMZ, shapefile, GeoJSON, GPX, LandXML, LAS, DGN, EPANET .inp, CSV/XYZ, GeoTIFF na picha; huhamisha DXF 2000 yenye vipengele asilia (au R12), DWG, PDF, PNG, SVG, KML/KMZ, GeoJSON, shapefile, GPX, LandXML, EPANET .inp na IFC.'),
    ('Katalogi za watengenezaji', 'Katalogi za watengenezaji katika JSON (Netafim, Rivulis, Jain, Toro, Rain Bird, Nelson, Hunter, NaanDanJain, Senninger, Irritec, Bermad, Schneider, Amanco Wavin, Multilit) tayari kutumika, pamoja na vifurushi vyako vinavyopakiwa kutoka faili au URL.'),
    ('Nje ya mtandao na shambani', 'Baada ya kutembelea tovuti mara ya kwanza, programu hufunguka bila intaneti, kwenye kompyuta, kishikwambi au simu, kwa mandhari ya mwanga au ya giza. Shambani, GPS ya kifaa hurekodi matembezi yako kama mipaka au mistari, huweka alama za nukta na huonyesha umbali na mwelekeo hadi kipengele kilichochaguliwa ili kuweka alama za usanifu ardhini.'),
  ],
  howTitle: 'Jinsi inavyofanya kazi',
  how: [
    ('Chora au ingiza eneo', 'Leta DXF, DWG, KML au picha ya setilaiti, chora shamba, bustani au uwanja moja kwa moja, au mwambie msaidizi wa AI anwani, naye atalipata eneo kwenye ramani. Ongeza mistari ya kontua au pakua mwinuko kwa kuratibu.'),
    ('Jenga mtandao, kwa mkono au kwa msaada wa AI', 'Tengeneza makundi ya laterali au gridi za vinyunyizio kwa mbofyo mmoja, au mwombe msaidizi wa AI apange vinyunyizio, agawe shamba, atandaze mabomba na aweke vali, pampu na chanzo cha maji; kisha uunganishe vyote kwa bomba kuu.'),
    ('Sanifu na uandike nyaraka', 'Bonyeza F5, au iombe AI ifanye hivyo: programu hupima ukubwa wa kanda na bomba kuu, hukagua shinikizo na kasi, na hutoa ripoti, orodha ya vifaa na karatasi ya PDF.'),
  ],
  examplesTitle: 'Mifano iliyo tayari kufunguliwa',
  examplesIntro: 'Kila mradi hufunguka ukiwa kamili na husanifiwa kwa F5. Itumie kujifunza programu au kama mahali pa kuanzia.',
  examples: [
    SiteExample('orchard', 'Bustani ya matunda', 'Vinyunyizio vidogo kwenye michungwa na matone kwenye zabibu, kisima chenye pampu na chujio, ardhi ya mteremko.'),
    SiteExample('garden', 'Bustani ya nyumbani', 'Vinyunyizio vya pop-up kwenye nyasi za mbele, rota nyuma na matone kwenye vitalu, vikilishwa na mtandao wa maji wenye mita na kizuia mtiririko wa nyuma.'),
    SiteExample('sportsField', 'Uwanja wa mpira', 'Uwanja kamili wa m 105 × 68 wenye vinyunyizio vya mgongano katika safu tano, hifadhi, pampu na zamu za usiku.'),
    SiteExample('rowCrop', 'Zao la mistari kwa matone', 'Vitalu vinne vya nyanya kwenye tepu ya matone, manifold zenye vali, chujio la wavu, pampu na ardhi ya mteremko.'),
    SiteExample('pivot', 'Pivoti ya kati', 'Pivoti ya m 300 kwenye mahindi inayolishwa na bomba kuu, kisima na pampu; ripoti ya minara, urefu na nozeli.'),
    SiteExample('greenhouse', 'Bustani ya kioo ya mboga', 'Vichuguu vinne vya pilipili hoho kwenye bomba la matone linalofidia shinikizo, kanda moja kwa kichuguu, tangi, pampu ndogo na chujio la diski.'),
    SiteExample('nursery', 'Kitalu cha miche', 'Vitalu vitatu vya m 12 × 48 chini ya vinyunyizio vidogo vya juu kwenye gridi ya m 4 × 4, kanda moja kwa kitalu, tangi lililoinuliwa, pampu ndogo na chujio la diski.'),
    SiteExample('coffee', 'Kahawa kwenye mistari ya kontua', 'Vitalu vitatu vya kahawa kwenye mlima vyenye laterali zilizopinda zinazofuata kontua (kundi lililoongozwa), bomba la matone la PC, kisima na pampu chini ya mteremko.'),
    SiteExample('bananas', 'Shamba la ndizi', 'Vitalu viwili vya ndizi chini ya vinyunyizio vidogo vinavyofidia shinikizo kwa m 5 × 5, kisima chenye pampu ya kuzamisha, chujio la diski na ardhi ya mteremko.'),
    SiteExample('sugarcane', 'Miwa kwa matone ya chini ya ardhi', 'Vitalu viwili vya miwa kwenye bomba la matone la PC la mm 20 lililozikwa m 0.3, laterali za m 180, manifold zilizozikwa, hifadhi, pampu, chujio la wavu na vali ya hewa.'),
    SiteExample('gravity', 'Matone kwa nguvu ya uvutano', 'Hifadhi m 40 juu ya vitalu viwili vya mboga vya matone, bila pampu: vali ya lango, vali ya kupunguza shinikizo na chujio la diski kwenye bomba kuu; kontua za mlima.'),
    SiteExample('pasture', 'Malisho ya vinyunyizio', 'Mazizi matatu ya m 72 × 72 yenye mistari ya vinyunyizio vya mgongano kwa m 12 × 18, manifold zenye vali, hifadhi, pampu na vali ya kuzuia.'),
    SiteExample('golf', 'Shimo la gofu', 'Tii yenye vinyunyizio, fairway yenye rota kwenye gridi ya pembetatu (kanda mbili) na green yenye rota kuzunguka ukingo, bwawa lenye pampu na zamu za usiku.'),
    SiteExample('sectorPivot', 'Pivoti ya sekta yenye bunduki ya mwisho', 'Pivoti ya m 250 kwenye soya inayozunguka 270°, ikiacha robo ya makazi ya shamba wazi, yenye bunduki ya mwisho ya m³/h 12; bwawa, pampu ya hp 20 na vali ya lango.'),
    SiteExample('linear', 'Mashine ya mstari', 'Mashine ya mstari ya m 392 kwenye ngano inayosafiri m 800 kando ya mfereji, kuchukua maji kwa pampu ya hp 30 na vali ya kuzuia; ripoti ya minara na nozeli.'),
  ],
  faqTitle: 'Maswali yanayoulizwa mara kwa mara',
  faq: [
    ('OpenCADIrrigation ni nini?', 'OpenCADIrrigation ni programu ya wavuti ya bure na huria ya kusanifu mifumo ya umwagiliaji wa shinikizo: CAD yenye injini ya haidroliki inayopanga mtandao, kupima ukubwa wa mabomba, kukagua shinikizo na usawa, na kutoa orodha ya vifaa na ripoti, kuanzia bustani ya nyumbani hadi pivoti ya kati, pamoja na msaidizi wa AI wa hiari anayechora na kusanifu mradi nawe kutokana na maelezo ya eneo.'),
    ('Je, akili bandia (AI) inaweza kunisanifia mradi?', 'Ndiyo, ukitaka. Msaidizi wa AI, ambaye ni wa hiari, hufanya kazi kwenye mradi uliofunguliwa kwa zana zilezile zilizo kwenye menyu: eleza eneo, au mwache atazame picha ya setilaiti na ardhi ya mradi wenye marejeleo ya kijiografia, naye hupanga vinyunyizio na matone, hugawa mashamba katika vitalu, hupanga njia za mabomba na vali, huweka pampu na chanzo cha maji, huendesha usanifu na zana za kiotomatiki, hurekebisha maonyo, hupunguza gharama na huandika ripoti. Huuliza kabla ya kila badiliko, au hutumia mabadiliko kiotomatiki ukichagua hivyo, na kila jibu linaweza kutenduliwa kwa mbofyo mmoja. Modeli inaweza kukosea, kwa hiyo kagua kazi yake kama ambavyo ungekagua kazi ya mwenzako.'),
    ('Inatumia modeli zipi za AI?', 'Modeli za Claude kutoka Anthropic (Claude Opus 5.5 kwa chaguomsingi, Claude Fable 5.1, Claude Sonnet 5.5 na Claude Haiku 5.5) na modeli za GPT kutoka OpenAI (GPT-6 Astra, GPT-6.1 Sol na GPT-6 Luna): daraja la juu, la kati na la haraka kwa kila kampuni, kila modeli ikiwa na viwango vitano vya kina cha kufikiri. Unachagua modeli katika mipangilio ya msaidizi na kubandika ufunguo wako mwenyewe wa API; paneli ya msaidizi huonyesha tokeni na gharama inayokadiriwa ya kila jibu, na kikomo cha hatua pamoja na kikomo cha matumizi husimamisha kazi inayorefuka kupita kiasi.'),
    ('Msaidizi wa AI hutuma nini, na wapi?', 'Hakuna chochote hadi ubonyeze Tuma. Hapo ujumbe wako, faili unazoambatisha na data ya mradi unayoiwekea alama huenda moja kwa moja kutoka kivinjari chako hadi kwenye API ya mtoa huduma uliyemchagua, Anthropic au OpenAI, bila seva yoyote ya OpenCADIrrigation katikati, pamoja na matokeo ya zana anazotumia wakati wa kujibu, zikiwemo picha za mchoro. Mtoa huduma hutoza gharama za matumizi kwenye akaunti yako. Ufunguo hubaki kwenye kumbukumbu kwa muda wa kipindi tu, isipokuwa uchague kuukumbuka kwenye kifaa, na kamwe hauingii kwenye faili za mradi, viungo vya kushiriki au faili zinazohamishwa. Kuimla kwa sauti, ukikitumia, hufanywa na utambuzi wa sauti wa kivinjari chenyewe, ambao hutuma sauti kwa kampuni iliyotengeneza kivinjari (Google kwenye Chrome, Microsoft kwenye Edge, Apple kwenye Safari). Mazungumzo yaliyohifadhiwa hubaki kwenye kivinjari chako, kamwe hayaingii kwenye faili za mradi au viungo.'),
    ('Je, OpenCADIrrigation ni bure?', 'Ndiyo. Ni bure kwa kazi za kitaalamu, masomo na matumizi binafsi, bila kujisajili. Pia ni programu huria chini ya leseni ya MIT, na msimbo chanzo wake umechapishwa kwenye GitHub. Msaidizi wa AI, ambaye ni wa hiari, hutumia akaunti yako mwenyewe ya Anthropic au OpenAI, na mtoa huduma hutoza gharama za matumizi yake kwenye akaunti hiyo.'),
    ('Ni kwa ajili ya nani?', 'Kwa wasanifu wa umwagiliaji wa kilimo na wa mandhari, wataalamu wa kilimo na wahandisi, wauzaji wa vifaa, walimu na wanafunzi. Mafunzo shirikishi, mifano 15 iliyo tayari na msaidizi wa AI hukuwezesha kuanza bila kusoma mwongozo.'),
    ('Je, ninahitaji kusakinisha chochote?', 'Hapana. Inafanya kazi kwenye Chrome, Edge, Firefox na Safari, kwenye kompyuta, kishikwambi na simu, na inaweza kusakinishwa kama programu (PWA) inayofunguka katika dirisha lake.'),
    ('Je, inafanya kazi bila intaneti?', 'Ndiyo, baada ya kutembelea tovuti mara ya kwanza: programu huhifadhi nakala yake kwenye kivinjari (takriban MB 24, mara moja kwa kila toleo), hivyo wakati ujao programu iliyosakinishwa au tovuti hufunguka na kufanya kazi bila intaneti, ofisini au shambani. Ramani za msingi, mwinuko na hali ya hewa kutoka mtandaoni, katalogi zinazopakiwa kutoka URL na msaidizi wa AI bado vinahitaji muunganisho wa intaneti; toleo jipya hupakuliwa chinichini na hutumika kuanzia mara inayofuata.'),
    ('Je, miradi yangu huhifadhiwa kwenye wingu?', 'Hapana. Miradi huhifadhiwa kwenye kivinjari chako na katika faili za .oci.json unazoweka popote upendapo; kiungo cha kushiriki hubeba mradi ndani ya anwani yenyewe, kwa hiyo hakuna kinachopakiwa kwenye seva. Intaneti hutumika tu unapoiomba: ramani za msingi, mwinuko na hali ya hewa kutoka mtandaoni, katalogi zinazopakiwa kutoka URL na, ukimtumia, msaidizi wa AI, ambaye huwasiliana tu na mtoa huduma uliyemchagua (Anthropic au OpenAI).'),
    ('Ukokotoaji wa haidroliki hufanywaje?', 'Upotevu wa msuguano kwa Hazen-Williams, Darcy-Weisbach, Scobey au Manning, vitoa-maji kwa q = k·Hˣ, na mtandao wote hutatuliwa kwa Global Gradient Algorithm, mbinu inayotumiwa na EPANET. Mabomba hupimwa kwa linear programming ndani ya dirisha la shinikizo la vitoa-maji na daraja la shinikizo la mabomba, na usanifu pia hukagua usawa (CU, DU, EU), usafishaji na hali za mpito kwa method of characteristics (kufungwa kwa vali, kusimama ghafla kwa pampu, vali za hewa), pamoja na uigaji wa saa 24 wa shinikizo na gharama ya nishati.'),
    ('Je, inafanya kazi na AutoCAD na CAD nyingine?', 'Ndiyo. Huingiza DXF na DWG hadi AutoCAD 2018, DGN V7 na michoro ya PDF, na huhamisha DXF 2000 yenye vipengele asilia (polyline zenye tao, vivuli, spline, vipimo, bloku zenye sifa), DXF R12 kwa programu za zamani na DWG 2000. Kwa GIS, upimaji ardhi na BIM pia huingiza na kuhamisha KML/KMZ, shapefile, GeoJSON, GPX, LandXML na EPANET .inp, huingiza mawingu ya nukta ya LAS na huhamisha IFC 4.'),
    ('Inapatikana kwa lugha zipi?', 'Kwa lugha 20, zile zile za tovuti hii (orodha iko chini ya ukurasa). Programu hufunguka kwa lugha ya kompyuta yako na unaweza kubadilisha wakati wowote kwenye Mwonekano → Lugha.'),
  ],
  loading: 'Inapakia CAD ya umwagiliaji…',
  slow: 'Upakiaji unachukua muda. Kagua muunganisho au pakia upya ukurasa; maudhui yaliyo juu tayari yanaweza kusomwa.',
